<?php
require_once __DIR__.'/../includes/functions.php';require_role(['staff','admin','super_admin']);$rows=db()->query("SELECT a.*,p.patient_number,COALESCE(NULLIF(p.full_name,''),pu.name,'Patient') patient_name,du.name doctor_name,dep.name department_name FROM appointments a JOIN patients p ON p.id=a.patient_id LEFT JOIN users pu ON pu.id=p.user_id JOIN doctors d ON d.id=a.doctor_id JOIN users du ON du.id=d.user_id JOIN departments dep ON dep.id=d.department_id WHERE a.appointment_date=CURRENT_DATE() ORDER BY a.start_at")->fetchAll();$pageTitle='Reception queue';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Front desk','Reception queue','Manage today’s patient flow and check-ins','<a class="btn btn-outline-primary" href="'.e(url('patients/register.php')).'"><i class="bi bi-person-plus me-1"></i>New patient</a><a class="btn btn-primary" href="'.e(url('appointments/book.php')).'"><i class="bi bi-calendar-plus me-1"></i>Book slot</a>');?>
<div class="row g-3 mb-4"><div class="col-md-4"><?=stat_card('Today’s appointments',(string)count($rows),'calendar-check','All doctors')?></div><div class="col-md-4"><?=stat_card('Checked in',(string)count(array_filter($rows,fn($a)=>$a['status']==='checked_in')),'person-check','Waiting in queue')?></div><div class="col-md-4"><?=stat_card('Confirmed',(string)count(array_filter($rows,fn($a)=>$a['status']==='confirmed')),'clock','Expected today')?></div></div><div class="card"><div class="card-header"><h2 class="section-title">Today's queue</h2></div><div class="table-responsive"><table class="table"><thead><tr><th>Token</th><th>Patient</th><th>Doctor</th><th>Time</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($rows as $a):?><tr><td><span class="badge text-bg-light border">#<?= (int)$a['token_number']?></span></td><td><strong><?=e($a['patient_name'])?></strong><div class="small-muted"><?=e($a['patient_number'])?></div></td><td><?=e($a['doctor_name'])?><div class="small-muted"><?=e($a['department_name'])?></div></td><td><?=e(substr($a['start_at'],0,5))?></td><td><?=status_badge($a['status'])?></td><td><?php if(in_array($a['status'],['requested','confirmed'],true)):?><form method="post" action="<?=e(url('appointments/update-status.php'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$a['id']?>"><input type="hidden" name="status" value="checked_in"><button class="btn btn-sm btn-outline-primary">Check in</button></form><?php else:?><span class="small-muted">—</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows)echo empty_row(6,'No appointments scheduled for today.');?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php';?>